415	      if (
416	        !isPlainObject(rec) ||
417	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
418	        !isPlainObject(rec.qty) ||
419	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
420	      )
