443	  if (data.returns !== undefined) {
444	    if (!isPlainObject(data.returns)) throw bad('returns 不是对象');
445	    for (const [retId, rec] of Object.entries(data.returns)) {
446	      if (typeof retId !== 'string' || retId.trim() === '') throw bad('存在非法退货单编号');
447	      if (store.docs[retId] !== undefined) throw bad(`退货单编号 ${retId} 与原始库存单据编号冲突`);
448	      if (store.arrivals[retId] !== undefined) throw bad(`退货单编号 ${retId} 与到货单编号冲突`);
449	      if (store.cancels[retId] !== undefined) throw bad(`退货单编号 ${retId} 与取消单编号冲突`);
450	      if (
451	        !isPlainObject(rec) ||
452	        typeof rec.arrId !== 'string' || rec.arrId.trim() === '' ||
453	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
454	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
455	        !isPlainObject(rec.qty) ||
456	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
457	      )
458	        throw bad(`退货单 ${retId} 的记录非法`);
