462	        qty[pid] = q;
463	      }
464	      if (Object.keys(qty).length === 0) throw bad(`退货单 ${retId} 至少需要一种商品`);
465	      const arr = store.arrivals[rec.arrId];
466	      if (arr === undefined) throw bad(`退货单 ${retId} 指向的原到货单 ${rec.arrId} 不存在`);
