478	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理。
479	  // 原单既可以是入库/出库/调拨/盘点单，也可以是到货单、取消单、退货单；冲销单不可冲销。
480	  if (data.reversals !== undefined) {
481	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
482	    for (const [revId, rec] of Object.entries(data.reversals)) {
483	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
484	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
485	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
486	        throw bad(`冲销单 ${revId} 的记录非法`);
487	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始库存单据编号冲突`);
488	      if (store.arrivals[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与到货单编号冲突`);
489	      if (store.cancels[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与取消单编号冲突`);
490	      if (store.returns[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与退货单编号冲突`);
491	      const origRec = store.docs[rec.orig];
492	      const origArr = store.arrivals[rec.orig];
493	      const origCan = store.cancels[rec.orig];
494	      const origRet = store.returns[rec.orig];
495	      if (origRec === undefined && origArr === undefined && origCan === undefined && origRet === undefined) {
496	        // 用 data.reversals 判定，避免依赖键的先后顺序（此时 store.reversals 可能尚未装全）
497	        if (isPlainObject((data.reversals as Record<string, unknown>)[rec.orig]))
498	          throw bad(`冲销单 ${rec.orig} 不可被再次冲销（冲销单不能冲销冲销单）`);
499	        if (store.purchases[rec.orig] !== undefined)
500	          throw bad(`冲销单 ${revId} 指向的 ${rec.orig} 是采购单，采购单不可冲销`);
501	        throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
502	      }
503	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
504	    }
505	    // 每张原单最多被成功冲销一次（库存单与到货单统一校验）
506	    const origSeen = nullProto<Record<string, string>>();
507	    for (const [revId, rec] of Object.entries(store.reversals)) {
508	      if (origSeen[rec.orig] !== undefined)
509	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
510	      origSeen[rec.orig] = revId;
511	    }
512	    // 冲销单不可冲销：冲销关系不能指向另一张冲销单
513	    for (const rec of Object.values(store.reversals)) {
514	      if (store.reversals[rec.orig] !== undefined)
515	        throw bad(`冲销单 ${rec.orig} 不可被再次冲销`);
516	    }
517	    // 冲销流水必须能找到所属冲销单
518	    for (const e of store.entries) {
519	      if (REV_ENTRY_TYPES.has(e.type) && store.reversals[e.doc] === undefined)
520	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
521	    }
522	  }
523	
524	  // 到货流水必须能找到所属到货单，且逐项数量/采购单/收货仓与记录一致；
525	  // 逐商品合计用 BigInt 精确累计，避免多条流水合计超过安全整数范围时舍入误判
526	  const arrivalEntrySeen = nullProto<Record<string, Record<string, bigint>>>();
527	  for (const e of store.entries) {
528	    if (e.type !== 'arrival') continue;
529	    const arr = store.arrivals[e.doc];
530	    if (arr === undefined) throw bad(`流水引用了不存在的到货单 ${e.doc}`);
531	    if (e.po !== arr.poId) throw bad(`到货单 ${e.doc} 流水的采购单编号与记录不一致`);
532	    if (e.wh !== arr.wh) throw bad(`到货单 ${e.doc} 流水的收货仓与记录不一致`);
533	    const perProduct = (arrivalEntrySeen[e.doc] ??= nullProto<Record<string, bigint>>());
534	    perProduct[e.product] = (perProduct[e.product] ?? 0n) + BigInt(e.qty!);
535	  }
536	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
537	    const seen = arrivalEntrySeen[arrId];
538	    if (seen === undefined) throw bad(`到货单 ${arrId} 缺少到货流水`);
539	    for (const [pid, q] of Object.entries(arr.qty)) {
540	      if (seen[pid] !== BigInt(q)) throw bad(`到货单 ${arrId} 商品 ${pid} 的流水数量与记录不一致`);
541	    }
542	    for (const pid of Object.keys(seen)) {
543	      if (arr.qty[pid] === undefined) throw bad(`到货单 ${arrId} 的流水含记录中没有的商品 ${pid}`);
544	    }
545	  }
546	
547	  // 冲销到货流水逐项数量必须与原到货单一致
548	  for (const e of store.entries) {
549	    if (e.type !== 'arrival-rev') continue;
550	    const rev = store.reversals[e.doc];
551	    if (rev === undefined) throw bad(`冲销到货流水引用了不存在的冲销单 ${e.doc}`);
552	    const arr = store.arrivals[rev.orig];
553	    if (arr === undefined) throw bad(`冲销单 ${e.doc} 指向的到货原单 ${rev.orig} 不存在`);
554	    if (e.po !== arr.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原到货单不一致`);
555	    if (arr.qty[e.product] !== e.qty)
556	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原到货单不一致`);
557	  }
558	
559	  // 退货流水必须能找到所属退货单，且逐项数量/原到货单/采购单/收货仓与记录一致（合计同样精确累计）
560	  const returnEntrySeen = nullProto<Record<string, Record<string, bigint>>>();
561	  for (const e of store.entries) {
562	    if (e.type !== 'return') continue;
563	    const ret = store.returns[e.doc];
564	    if (ret === undefined) throw bad(`流水引用了不存在的退货单 ${e.doc}`);
565	    if (e.arr !== ret.arrId) throw bad(`退货单 ${e.doc} 流水的原到货单编号与记录不一致`);
566	    if (e.po !== ret.poId) throw bad(`退货单 ${e.doc} 流水的采购单编号与记录不一致`);
567	    if (e.wh !== ret.wh) throw bad(`退货单 ${e.doc} 流水的收货仓与记录不一致`);
568	    const perProduct = (returnEntrySeen[e.doc] ??= nullProto<Record<string, bigint>>());
569	    perProduct[e.product] = (perProduct[e.product] ?? 0n) + BigInt(e.qty!);
570	  }
571	  for (const [retId, ret] of Object.entries(store.returns)) {
572	    const seen = returnEntrySeen[retId];
573	    if (seen === undefined) throw bad(`退货单 ${retId} 缺少退货流水`);
574	    for (const [pid, q] of Object.entries(ret.qty)) {
575	      if (seen[pid] !== BigInt(q)) throw bad(`退货单 ${retId} 商品 ${pid} 的流水数量与记录不一致`);
576	    }
577	    for (const pid of Object.keys(seen)) {
578	      if (ret.qty[pid] === undefined) throw bad(`退货单 ${retId} 的流水含记录中没有的商品 ${pid}`);
579	    }
580	  }
581	
582	  // 冲销退货流水逐项数量必须与原退货单一致
583	  for (const e of store.entries) {
584	    if (e.type !== 'return-rev') continue;
585	    const rev = store.reversals[e.doc];
586	    if (rev === undefined) throw bad(`冲销退货流水引用了不存在的冲销单 ${e.doc}`);
587	    const ret = store.returns[rev.orig];
588	    if (ret === undefined) throw bad(`冲销单 ${e.doc} 指向的退货原单 ${rev.orig} 不存在`);
589	    if (e.arr !== ret.arrId) throw bad(`冲销单 ${e.doc} 流水的原到货单编号与原退货单不一致`);
590	    if (e.po !== ret.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原退货单不一致`);
591	    if (ret.qty[e.product] !== e.qty)
592	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原退货单不一致`);
593	  }
594	
595	  // 退货不变量：同一原到货单的未冲销累计退货不得超过原到货量；
596	  // 有未冲销退货的到货单禁止冲销（已冲销到货的全部退货必须已冲销）
597	  for (const [retId, ret] of Object.entries(store.returns)) {
598	    const retReversed = Object.values(store.reversals).some((r) => r.orig === retId);
599	    if (retReversed) continue;
600	    if (Object.values(store.reversals).some((r) => r.orig === ret.arrId))
601	      throw bad(`到货单 ${ret.arrId} 已整单冲销，但其退货单 ${retId} 未冲销（有未冲销退货的到货单禁止冲销）`);
602	    const arr = store.arrivals[ret.arrId];
603	    const sumByPid = nullProto<Record<string, bigint>>();
604	    for (const [otherId, other] of Object.entries(store.returns)) {
605	      if (other.arrId !== ret.arrId) continue;
606	      if (Object.values(store.reversals).some((r) => r.orig === otherId)) continue;
607	      for (const [pid, q] of Object.entries(other.qty)) sumByPid[pid] = (sumByPid[pid] ?? 0n) + BigInt(q);
608	    }
609	    for (const [pid, sum] of Object.entries(sumByPid)) {
610	      if (sum > BigInt(arr.qty[pid]))
611	        throw bad(`到货单 ${ret.arrId} 商品 ${pid} 未冲销累计退货 ${sum} 超过原到货量 ${arr.qty[pid]}`);
612	    }
613	  }
614	
615	  // 冲销流水类型必须与原单业务类型一致（入库→in-rev、到货→arrival-rev、退货→return-rev 等）；
616	  // 取消单冲销不产生库存流水（取消本身不改库存），故不要求、也不允许携带流水。
617	  const revIdsWithEntries = nullProto<Record<string, boolean>>();
618	  for (const [revId, rev] of Object.entries(store.reversals)) {
619	    const origDoc = store.docs[rev.orig];
620	    // 原单为取消单时（前面已确认必为库存单/到货单/取消单/退货单之一）不应存在任何冲销流水
621	    let expected: EntryType | undefined;
622	    if (origDoc !== undefined) expected = `${origDoc.content.type}-rev` as EntryType;
623	    else if (store.arrivals[rev.orig] !== undefined) expected = 'arrival-rev';
624	    else if (store.returns[rev.orig] !== undefined) expected = 'return-rev';
625	    for (const e of store.entries) {
626	      if (e.doc !== revId) continue;
627	      if (expected === undefined)
628	        throw bad(`冲销单 ${revId} 冲销的是取消单 ${rev.orig}，不应携带库存流水`);
629	      revIdsWithEntries[revId] = true;
630	      if (e.type !== expected)
631	        throw bad(`冲销单 ${revId} 的流水类型与原单 ${rev.orig} 的业务类型不一致`);
632	    }
633	    if (expected !== undefined) revIdsWithEntries[revId] ??= false;
634	  }
635	  for (const revId of Object.keys(store.reversals)) {
636	    if (revIdsWithEntries[revId] === false) throw bad(`冲销单 ${revId} 缺少冲销流水`);
637	  }
638	
639	  // 采购进度不变量：有效到货 = 未冲销到货 - 未冲销退货；任一商品
640	  // “有效到货 + 未冲销累计取消”不得超过订购量
641	  // （待到货量 = 订购量 - 有效到货量 - 有效取消量，不得为负）。
642	  // 注意：退货释放待到货后允许再次到货，故未冲销到货总量本身可以超过订购量，
643	  // 甚至可以超过安全整数范围（反复退货、补收）——必须先抵减未冲销退货再校验，
644	  // 且全程用 BigInt 精确累计，不得因中间累计舍入而改变净量或误拒合法数据。
645	  for (const [poId, po] of Object.entries(store.purchases)) {
646	    const arrived = nullProto<Record<string, bigint>>();
647	    for (const [arrId, arr] of Object.entries(store.arrivals)) {
648	      if (arr.poId !== poId) continue;
649	      const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
650	      if (isReversed) continue; // 已整单冲销的到货不再计入有效到货
651	      for (const [pid, q] of Object.entries(arr.qty)) {
652	        arrived[pid] = (arrived[pid] ?? 0n) + BigInt(q);
653	      }
654	    }
655	    // 未冲销退货抵减有效到货（前面已保证其原到货单未冲销且不超退）
656	    for (const [retId, ret] of Object.entries(store.returns)) {
657	      if (ret.poId !== poId) continue;
658	      const isReversed = Object.values(store.reversals).some((r) => r.orig === retId);
659	      if (isReversed) continue;
660	      for (const [pid, q] of Object.entries(ret.qty)) {
661	        arrived[pid] = (arrived[pid] ?? 0n) - BigInt(q);
662	        if (arrived[pid] < 0n)
663	          throw bad(`采购单 ${poId} 商品 ${pid} 未冲销累计退货超过有效到货量`);
664	      }
665	    }
666	    for (const [pid, q] of Object.entries(arrived)) {
667	      if (q > BigInt(po.ordered[pid] ?? 0))
668	        throw bad(`采购单 ${poId} 商品 ${pid} 有效到货（未冲销到货减未冲销退货）超过订购量`);
669	    }
670	    const cancelled = nullProto<Record<string, bigint>>();
671	    for (const [canId, can] of Object.entries(store.cancels)) {
672	      if (can.poId !== poId) continue;
673	      const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
674	      if (isReversed) continue; // 已整单冲销的取消不再计入有效取消
675	      for (const [pid, q] of Object.entries(can.qty)) {
676	        cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
677	        if ((arrived[pid] ?? 0n) + cancelled[pid] > BigInt(po.ordered[pid]))
678	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消合计超过订购量（待到货量为负）`);
679	      }
680	    }
681	  }
