871	function saveStore(dataDir: string, store: Store): void {
872	  const path = dataPath(dataDir);
873	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
874	  try {
875	    mkdirSync(dataDir, { recursive: true });
876	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
877	    renameSync(tmp, path);
878	  } catch (e) {
879	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
880	  }
881	}
