938	interface DocRequest {
939	  type: DocType;
940	  docId: string;
941	  wh?: string;
942	  from?: string;
943	  to?: string;
944	  items: Map<string, number>;
945	}
946	
947	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
948	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
949	  const docId = args.positionals[0];
950	  if (docId === undefined || args.positionals.length !== 1)
951	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
952	
953	  const items = new Map<string, number>();
954	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
955	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
956	
957	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
958	  if (type === 'transfer') {
959	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
960	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
961	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
962	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
963	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
964	  } else {
965	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
966	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
967	  }
968	  return req;
969	}
