971	interface CountItem {
972	  expected: number; // 预期账面量
973	  actual: number; // 实盘量
974	}
975	
976	interface CountRequest {
977	  docId: string;
978	  wh: string;
979	  items: Map<string, CountItem>;
980	}
981	
982	function parseNonNegInt(label: string, raw: string): number {
983	  const s = raw.trim();
984	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
985	  const n = Number(s);
986	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
987	  return n;
988	}
989	
990	function parseCountArgs(tokens: string[]): CountRequest {
991	  const args = parseArgs(tokens, ['--wh'], ['--item']);
992	  const docId = args.positionals[0];
993	  if (docId === undefined || args.positionals.length !== 1)
994	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
995	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
996	
997	  const items = new Map<string, CountItem>();
998	  for (const raw of args.multi['--item'] ?? []) {
999	    const parts = raw.split(':');
1000	    if (parts.length !== 3)
1001	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
1002	    const pid = trimOrThrow('商品编号', parts[0]);
1003	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
1004	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
1005	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
1006	    items.set(pid, { expected, actual });
1007	  }
1008	  if (items.size === 0)
1009	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
1010	
1011	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
1012	}
