1053	  return {
1054	    poId: trimOrThrow('采购编号', poRaw),
1055	    supplier: trimOrThrow('供应商名称', args.flags['--supplier']),
1056	    wh: trimOrThrow('收货仓标识', args.flags['--wh']),
1057	    items,
1058	  };
