1069	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
1070	  if (items.size === 0) throw new UsageError('到货单至少需要一条 --item 商品编号:到货量 明细');
1071	
1072	  return { arrId: trimOrThrow('到货单编号', arrRaw), poId: trimOrThrow('采购编号', args.flags['--po']), items };
1073	}
1074	
1075	function parseCancelArgs(tokens: string[]): CancelRequest {
1076	  const args = parseArgs(tokens, ['--po'], ['--item']);
1077	  const canRaw = args.positionals[0];
1078	  if (canRaw === undefined || args.positionals.length !== 1)
