1289	function canonicalContent(req: DocRequest): Record<string, unknown> {
1290	  const items: Record<string, number> = nullProto();
1291	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
1292	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
1293	  return { type: req.type, wh: req.wh!, items };
