1304	/**
1305	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
1306	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
1307	 */
1308	function cloneStock(stock: Store['stock']): Store['stock'] {
1309	  const out = nullProto<Store['stock']>();
1310	  for (const pid of Object.keys(stock)) {
1311	    const whMap = nullProto<Record<string, number>>();
1312	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
1313	    out[pid] = whMap;
1314	  }
1315	  return out;
1316	}
1317	
1318	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
1319	  const items: Record<string, unknown> = nullProto();
1320	  for (const pid of [...req.items.keys()].sort()) {
1321	    const it = req.items.get(pid)!;
1322	    items[pid] = { expected: it.expected, actual: it.actual };
1323	  }
1324	  return { type: 'count', wh: req.wh, items };
1325	}
