1327	/** 采购单规范化内容：明细按商品编号排序，比较时与明细顺序无关。 */
1328	function canonicalPurchaseContent(req: PurchaseRequest): {
1329	  supplier: string;
1330	  wh: string;
1331	  ordered: Record<string, number>;
1332	} {
1333	  const ordered: Record<string, number> = nullProto();
1334	  for (const pid of [...req.items.keys()].sort()) ordered[pid] = req.items.get(pid)!;
1335	  return { supplier: req.supplier, wh: req.wh, ordered };
1336	}
1337	
1338	/** 到货明细规范化：合并后数量按商品编号排序。 */
1339	function canonicalArrivalItems(items: Map<string, number>): Record<string, number> {
1340	  const out: Record<string, number> = nullProto();
1341	  for (const pid of [...items.keys()].sort()) out[pid] = items.get(pid)!;
1342	  return out;
1343	}
