1345	interface ApplyOutcome {
1346	  duplicate: boolean;
1347	  header: string; // 结果首行汇总
1348	  lines: string[]; // 逐项明细结果
1349	  repeatedFrom?: 'store' | 'batch'; // 重复项来自导入前已存数据，还是本批此前各项
1350	}
