2409	function formatEntry(e: LedgerEntry): string {
2410	  let line: string;
2411	  if (e.type === 'count' || e.type === 'count-rev') {
2412	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
2413	    line =
2414	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
2415	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
2416	  } else {
2417	    let signed: string;
2418	    // 符号必须与前后余量一致：入库/冲销出库/到货/冲销退货/调入方向为增，其余为减
2419	    const increases =
2420	      e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev' ||
2421	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
2422	        (e.type === 'transfer') === (e.wh === e.to));
2423	    signed = `${increases ? '+' : '-'}${e.qty}`;
2424	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
2425	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
2426	    if (e.po !== undefined) line += `\t采购单=${e.po}`;
2427	    if (e.arr !== undefined) line += `\t原到货单=${e.arr}`;
2428	  }
2429	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
2430	  return line;
2431	}
