2715	 * 下限与目标均为非负安全整数且下限小于目标。规则随数据文件原子保存，
2716	 * 保存成功后才报告成功，失败保留已提交状态。
2717	 */
2718	function runRule(rest: string[], dataDir: string, store: Store): void {
2719	  const sub = rest[0];
2720	  const tokens = rest.slice(1);
2721	  if (sub === 'set') {
2722	    const args = parseArgs(tokens, ['--wh', '--min', '--target']);
2723	    const [pidRaw, ...extra] = args.positionals;
2724	    if (pidRaw === undefined || extra.length > 0)
2725	      throw new UsageError('用法：rule set <商品编号> --wh <仓库> --min <下限> --target <目标>');
2726	    if (args.flags['--wh'] === undefined) throw new UsageError('补货规则必须提供 --wh <仓库>');
2727	    if (args.flags['--min'] === undefined) throw new UsageError('补货规则必须提供 --min <下限>');
2728	    if (args.flags['--target'] === undefined) throw new UsageError('补货规则必须提供 --target <目标>');
2729	    const pid = trimOrThrow('商品编号', pidRaw);
2730	    const wh = trimOrThrow('仓库标识', args.flags['--wh']);
2731	    const min = parseNonNegInt('下限', args.flags['--min']);
2732	    const target = parseNonNegInt('目标', args.flags['--target']);
2733	    if (min >= target) throw new BizError(`下限 ${min} 必须小于目标 ${target}，拒绝设置`);
2734	    if (store.products[pid] === undefined) throw new BizError(`商品未登记，拒绝设置补货规则：${pid}`);
2735	    const byWh = (store.rules[pid] ??= nullProto<Record<string, ReplenishRule>>());
2736	    const replaced = byWh[wh] !== undefined;
2737	    byWh[wh] = { min, target }; // 同组合再次设置：整体替换原规则
2738	    saveStore(dataDir, store);
2739	    console.log(
2740	      replaced
2741	        ? `已替换补货规则：商品 ${pid} 仓库 ${wh}，下限 ${min}，目标 ${target}（原规则已整体替换）`
2742	        : `已设置补货规则：商品 ${pid} 仓库 ${wh}，下限 ${min}，目标 ${target}`,
2743	    );
2744	    return;
2745	  }
2746	  if (sub === 'list' || sub === 'ls') {
2747	    const args = parseArgs(tokens, []);
2748	    if (args.positionals.length > 0) throw new UsageError('用法：rule list');
2749	    const pids = Object.keys(store.rules).sort();
2750	    const total = pids.reduce((n, p) => n + Object.keys(store.rules[p]).length, 0);
2751	    console.log(`补货规则（${total}）：`);
2752	    if (total === 0) {
2753	      console.log('（暂无补货规则）');
2754	      return;
2755	    }
2756	    console.log('商品\t仓库\t下限\t目标');
2757	    for (const pid of pids) {
2758	      for (const wh of Object.keys(store.rules[pid]).sort()) {
2759	        const r = store.rules[pid][wh];
2760	        console.log(`${pid}\t${wh}\t${r.min}\t${r.target}`);
2761	      }
2762	    }
2763	    return;
2764	  }
2765	  if (sub === 'delete' || sub === 'del') {
2766	    const args = parseArgs(tokens, ['--wh']);
2767	    const [pidRaw, ...extra] = args.positionals;
2768	    if (pidRaw === undefined || extra.length > 0)
2769	      throw new UsageError('用法：rule delete <商品编号> --wh <仓库>');
2770	    if (args.flags['--wh'] === undefined) throw new UsageError('删除补货规则必须提供 --wh <仓库>');
2771	    const pid = trimOrThrow('商品编号', pidRaw);
2772	    const wh = trimOrThrow('仓库标识', args.flags['--wh']);
2773	    const byWh = store.rules[pid];
2774	    if (byWh === undefined || byWh[wh] === undefined)
2775	      throw new BizError(`商品 ${pid} 仓库 ${wh} 的补货规则不存在，无法删除`);
2776	    const removed = byWh[wh];
2777	    delete byWh[wh];
2778	    if (Object.keys(byWh).length === 0) delete store.rules[pid]; // 不留下空商品条目
2779	    saveStore(dataDir, store);
2780	    console.log(`已删除补货规则：商品 ${pid} 仓库 ${wh}（原下限 ${removed.min}，目标 ${removed.target}）`);
2781	    return;
2782	  }
2783	  throw new UsageError(sub === undefined ? '用法：rule <set|list|delete> …' : `未知 rule 子命令：${sub}`);
2784	}
