2801	/**
2802	 * 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商），
2803	 * 待到货 = 订购 - 有效到货 - 有效取消；BigInt 精确累计，超安全整数合计不舍入。
2804	 * 补货建议与方案快照/核对共用同一计算，保证口径一致。
2805	 */
2806	function pendingTotals(store: Store): Record<string, Record<string, bigint>> {
2807	  const pendingByCombo = nullProto<Record<string, Record<string, bigint>>>();
2808	  for (const poId of Object.keys(store.purchases)) {
2809	    const po = store.purchases[poId];
2810	    const { remaining } = purchaseProgress(store, poId); // 待到货 = 订购 - 有效到货 - 有效取消
2811	    for (const [pid, wait] of Object.entries(remaining)) {
2812	      if (wait === 0n) continue;
2813	      const byWh = (pendingByCombo[pid] ??= nullProto<Record<string, bigint>>());
2814	      byWh[po.wh] = (byWh[po.wh] ?? 0n) + wait;
2815	    }
2816	  }
2817	  return pendingByCombo;
2818	}
