2820	/**
2821	 * 跨仓补货建议（只读计算，不写文件、不改库存或采购；同状态结果一致）：
2822	 * 每个已配置（商品, 仓库）组合的预计量 = 本仓实存 + 本仓待到货合计
2823	 * （收货仓为本仓的全部采购单：待到货 = 订购 - 有效到货 - 有效取消，不限供应商；
2824	 * 其他仓库存不计入）。预计量不高于下限才触发，缺口 = 目标 - 预计量。
2825	 * 按商品分别分配：同商品其他已配置仓实存超过自身目标的部分可供调拨（待收不可调，
2826	 * 未配置仓既不产生需求也不提供调拨）；缺货仓、来源仓各按标识升序依次取量，
2827	 * 整份建议对来源的累计分配不超过可供量；剩余缺口即采购量。
2828	 * 合计、比较与分配一律用 BigInt 精确整数计算。
2829	 */
2830	function computeReplenish(store: Store): ReplenishSuggestion[] {
2831	  // 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商）
2832	  const pendingByCombo = pendingTotals(store);
2833	
2834	  const combos: ReplenishSuggestion[] = [];
2835	  for (const pid of Object.keys(store.rules).sort()) {
2836	    for (const wh of Object.keys(store.rules[pid]).sort()) {
2837	      const rule = store.rules[pid][wh];
2838	      const onHand = getStock(store.stock, pid, wh); // 无库存记录视为零
2839	      const pending = pendingByCombo[pid]?.[wh] ?? 0n;
2840	      const projected = BigInt(onHand) + pending;
2841	      const triggered = projected <= BigInt(rule.min); // 不高于下限才触发
2842	      combos.push({
2843	        pid, wh, min: rule.min, target: rule.target, onHand, pending, projected,
2844	        triggered, gap: triggered ? BigInt(rule.target) - projected : 0n,
2845	        transfers: [], transferTotal: 0n, purchase: 0n,
2846	      });
2847	    }
2848	  }
2849	
2850	  // 按商品分别分配调拨：缺货仓与来源仓均按标识升序（combos 已按商品、仓库升序）
2851	  const byProduct = new Map<string, ReplenishSuggestion[]>();
2852	  for (const c of combos) {
2853	    const list = byProduct.get(c.pid) ?? [];
2854	    list.push(c);
2855	    byProduct.set(c.pid, list);
2856	  }
2857	  for (const list of byProduct.values()) {
2858	    // 可供调拨量 = 实存 - 自身目标（仅实存超过目标的部分；待收不可调）
2859	    const sources = list
2860	      .filter((c) => BigInt(c.onHand) > BigInt(c.target))
2861	      .map((c) => ({ wh: c.wh, available: BigInt(c.onHand) - BigInt(c.target) }));
2862	    for (const deficit of list) {
2863	      if (!deficit.triggered) continue;
2864	      let rest = deficit.gap;
2865	      for (const src of sources) {
2866	        if (rest === 0n) break;
2867	        if (src.wh === deficit.wh || src.available === 0n) continue; // 缺货仓实存必低于目标，防御性跳过
2868	        const take = src.available < rest ? src.available : rest;
2869	        deficit.transfers.push({ from: src.wh, qty: take });
2870	        deficit.transferTotal += take;
2871	        src.available -= take; // 整份建议对来源的累计分配不超过可供量
2872	        rest -= take;
2873	      }
2874	      deficit.purchase = rest; // 剩余缺口即采购量（可为零）
2875	    }
2876	  }
2877	  return combos;
2878	}
2879	
2880	function runReplenish(rest: string[], store: Store): void {
2881	  const args = parseArgs(rest, []);
2882	  if (args.positionals.length > 0) throw new UsageError('用法：replenish');
2883	  if (Object.keys(store.rules).length === 0) {
2884	    console.log('未配置任何补货规则，无补货建议（可先用 rule set 为商品与仓库设置下限与目标）。');
2885	    return;
2886	  }
2887	  const combos = computeReplenish(store);
2888	  const triggeredCount = combos.filter((c) => c.triggered).length;
2889	  console.log(`补货建议（规则 ${combos.length} 条，触发 ${triggeredCount} 条）：`);
2890	  for (const c of combos) {
2891	    console.log(
2892	      `商品 ${c.pid} 仓库 ${c.wh}：下限 ${c.min}，目标 ${c.target}，实存 ${c.onHand}，` +
2893	        `待到货合计 ${c.pending}，预计量 ${c.projected}，` +
2894	        (c.triggered ? `触发补货，缺口 ${c.gap}` : '未触发'),
2895	    );
2896	    if (c.triggered) {
2897	      for (const t of c.transfers) console.log(`  调拨 ${t.from} -> ${c.wh}：${t.qty}`);
2898	      console.log(`  调拨合计 ${c.transferTotal}，采购量 ${c.purchase}`);
2899	    }
2900	  }
2901	  if (triggeredCount === 0) console.log('所有组合预计量均高于下限，无缺货，无需补货。');
2902	}
