2929	/**
2930	 * 解析 plan save 参数。标识去首尾空白后非空、区分大小写；
2931	 * 格式错误（缺参数、明细段数不对、同一调拨/采购重复指定）属于用法错误（退出 2），
2932	 * 子单编号在方案内重复使用属于业务拒绝（退出 1）。
2933	 */
2934	function parsePlanSaveArgs(tokens: string[]): PlanSaveSpec {
2935	  const args = parseArgs(tokens, [], ['--transfer', '--purchase']);
2936	  const [planRaw, ...extra] = args.positionals;
2937	  if (planRaw === undefined || extra.length > 0)
2938	    throw new UsageError(
2939	      '用法：plan save <方案编号> --transfer <商品>:<来源仓>:<目标仓>:<子单编号> [...] ' +
2940	        '--purchase <商品>:<收货仓>:<子单编号>:<供应商> [...]',
2941	    );
2942	  const planId = trimOrThrow('方案编号', planRaw);
2943	
2944	  const transfers: PlanSaveSpec['transfers'] = [];
2945	  const seenTransfer = new Set<string>();
2946	  for (const raw of args.multi['--transfer'] ?? []) {
2947	    const parts = raw.split(':');
2948	    if (parts.length !== 4)
2949	      throw new UsageError(`调拨子单格式应为 “商品:来源仓:目标仓:子单编号”：${raw}`);
2950	    const product = trimOrThrow('商品编号', parts[0]);
2951	    const from = trimOrThrow('来源仓标识', parts[1]);
2952	    const to = trimOrThrow('目标仓标识', parts[2]);
2953	    const docId = trimOrThrow('调拨子单编号', parts[3]);
2954	    const key = `${product}\0${from}\0${to}`;
2955	    if (seenTransfer.has(key)) throw new UsageError(`调拨子单 ${key} 重复指定`);
2956	    seenTransfer.add(key);
2957	    transfers.push({ product, from, to, docId });
2958	  }
2959	
2960	  const purchases: PlanSaveSpec['purchases'] = [];
2961	  const seenPurchase = new Set<string>();
2962	  for (const raw of args.multi['--purchase'] ?? []) {
2963	    const parts = raw.split(':');
2964	    if (parts.length < 4)
2965	      throw new UsageError(`采购子单格式应为 “商品:收货仓:子单编号:供应商”：${raw}`);
2966	    const product = trimOrThrow('商品编号', parts[0]);
2967	    const wh = trimOrThrow('收货仓标识', parts[1]);
2968	    const poId = trimOrThrow('采购子单编号', parts[2]);
2969	    const supplier = trimOrThrow('供应商名称', parts.slice(3).join(':')); // 供应商可含冒号
2970	    const key = `${product}\0${wh}`;
2971	    if (seenPurchase.has(key)) throw new UsageError(`采购子单 ${key} 重复指定`);
2972	    seenPurchase.add(key);
2973	    purchases.push({ product, wh, poId, supplier });
2974	  }
2975	
2976	  const seenDoc = new Set<string>();
2977	  for (const t of transfers) {
2978	    if (seenDoc.has(t.docId)) throw new BizError(`调拨子单编号 ${t.docId} 在方案中重复使用，拒绝保存`);
2979	    seenDoc.add(t.docId);
2980	  }
2981	  const seenPo = new Set<string>();
2982	  for (const p of purchases) {
2983	    if (seenPo.has(p.poId)) throw new BizError(`采购子单编号 ${p.poId} 在方案中重复使用，拒绝保存`);
2984	    seenPo.add(p.poId);
2985	  }
2986	
2987	  return { planId, transfers, purchases };
2988	}
