3117	    const cur = store.rules[pid] ?? nullProto<Record<string, ReplenishRule>>();
3118	    for (const [wh, s] of Object.entries(snap.rules[pid])) {
3119	      const c = cur[wh];
3120	      if (c === undefined)
3121	        diffs.push(`商品 ${pid} 仓库 ${wh} 的补货规则已删除（快照下限 ${s.min}，目标 ${s.target}）`);
3122	      else if (c.min !== s.min || c.target !== s.target)
3123	        diffs.push(
3124	          `商品 ${pid} 仓库 ${wh} 的补货规则已变化：快照下限 ${s.min}、目标 ${s.target}，当前下限 ${c.min}、目标 ${c.target}`,
3125	        );
3126	    }
3127	    for (const [wh, c] of Object.entries(cur)) {
3128	      if (snap.rules[pid][wh] === undefined)
3129	        diffs.push(`商品 ${pid} 仓库 ${wh} 新增补货规则（下限 ${c.min}，目标 ${c.target}）`);
3130	    }
3131	  }
3132	  for (const [pid, whs] of Object.entries(snap.stock)) {
3133	    for (const [wh, v] of Object.entries(whs)) {
3134	      const cur = getStock(store.stock, pid, wh);
3135	      if (cur !== v) diffs.push(`商品 ${pid} 仓库 ${wh} 实存：快照 ${v}，当前 ${cur}`);
3136	    }
3137	  }
3138	  const pendingNow = pendingTotals(store);
3139	  for (const [pid, whs] of Object.entries(snap.pending)) {
3140	    for (const [wh, v] of Object.entries(whs)) {
3141	      const cur = (pendingNow[pid]?.[wh] ?? 0n).toString();
3142	      if (cur !== v) diffs.push(`商品 ${pid} 仓库 ${wh} 待到货合计：快照 ${v}，当前 ${cur}`);
