3156	function runPlanExecute(tokens: string[], dataDir: string, store: Store): void {
3157	  const args = parseArgs(tokens, []);
3158	  const [planRaw, ...extra] = args.positionals;
3159	  if (planRaw === undefined || extra.length > 0) throw new UsageError('用法：plan execute <方案编号>');
3160	  const planId = trimOrThrow('方案编号', planRaw);
3161	  const plan = store.plans[planId];
3162	  if (plan === undefined) throw new BizError(`补货方案 ${planId} 不存在`);
3163	
3164	  if (plan.status === 'executed') {
3165	    console.log(`补货方案 ${planId} 已执行，返回原落单结果（不再核对快照、不再生效、不改写文件）：`);
3166	    for (const line of plan.execResultLines!) console.log(line);
3167	    return;
3168	  }
3169	
3170	  const diffs = planSnapshotDiffs(store, plan);
3171	  if (diffs.length > 0)
3172	    throw new BizError(
3173	      `补货方案 ${planId} 已过期，快照与当前状态不一致，整案拒绝执行（不替换为新建议）：\n${diffs.join('\n')}`,
3174	    );
3175	
3176	  // 子单编号占用检查：任一拟用编号已被对应空间占用即整案拒绝（即使内容相同也不接管）
3177	  for (const t of plan.transfers) {
3178	    if (
3179	      store.docs[t.docId] !== undefined || store.arrivals[t.docId] !== undefined ||
3180	      store.cancels[t.docId] !== undefined || store.returns[t.docId] !== undefined ||
3181	      store.reversals[t.docId] !== undefined
3182	    )
3183	      throw new BizError(`调拨子单编号 ${t.docId} 已被占用，整案拒绝执行（不接管已有单据）`);
3184	  }
3185	  for (const p of plan.purchases) {
3186	    if (store.purchases[p.poId] !== undefined)
3187	      throw new BizError(`采购子单编号 ${p.poId} 已被占用，整案拒绝执行（不接管已有单据）`);
3188	  }
3189	
3190	  // 模拟执行：任一子单失败（缺货、溢出、编号冲突）整案不留变动
3191	  const ledger = new Ledger(store);
3192	  const lines: string[] = [];
3193	  for (const t of plan.transfers) {
3194	    const outcome = ledger.applyDoc({
3195	      type: 'transfer', docId: t.docId, from: t.from, to: t.to,
3196	      items: new Map([[t.product, t.qty]]),
3197	    });
3198	    lines.push(outcome.header, ...outcome.lines);
3199	  }
3200	  for (const p of plan.purchases) {
3201	    const outcome = ledger.applyPurchase({
3202	      poId: p.poId, supplier: p.supplier, wh: p.wh,
3203	      items: new Map([[p.product, p.qty]]),
3204	    });
3205	    lines.push(outcome.header, ...outcome.lines);
3206	  }
3207	
3208	  // 全部子单通过：方案关联、执行状态与原结果随子单一次原子保存
3209	  plan.status = 'executed';
3210	  plan.execResultLines = lines;
3211	  ledger.commit(dataDir);
3212	
3213	  console.log(`补货方案 ${planId} 执行成功，全部子单已落单：`);
3214	  for (const line of lines) console.log(line);
3215	}
