3301	/**
3302	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
3303	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
3304	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
3305	 */
3306	function runImport(rest: string[], dataDir: string): void {
3307	  const args = parseArgs(rest, ['--file']);
3308	  const file = args.flags['--file'];
3309	  if (file === undefined || args.positionals.length > 0)
3310	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
3311	
3312	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
3313	  const requests = parseImportFile(readImportFile(file));
3314	
3315	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
3316	  const store = loadStore(dataDir);
3317	  const ledger = new Ledger(store);
3318	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
3319	  const blocks: string[] = [];
3320	  let newCount = 0;
3321	
3322	  requests.forEach((r, i) => {
3323	    const pos = `第 ${i + 1}/${requests.length} 项`;
3324	    // 模拟阶段的业务拒绝同样标注列表位置与原因
3325	    const apply = (): ApplyOutcome => {
3326	      switch (r.kind) {
3327	        case 'doc': return ledger.applyDoc(r.req);
3328	        case 'count': return ledger.applyCount(r.req);
3329	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
3330	        case 'po': return ledger.applyPurchase(r.req);
3331	        case 'arrival': return ledger.applyArrival(r.req);
3332	        case 'cancel': return ledger.applyCancel(r.req);
3333	        case 'return': return ledger.applyReturn(r.req);
3334	      }
3335	    };
3336	    let outcome: ApplyOutcome;
3337	    try {
3338	      outcome = apply();
3339	    } catch (e) {
3340	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
3341	      throw e;
3342	    }
3343	    const id =
3344	      r.kind === 'reverse' ? r.docId
3345	      : r.kind === 'po' ? r.req.poId
3346	      : r.kind === 'arrival' ? r.req.arrId
3347	      : r.kind === 'cancel' ? r.req.canId
3348	      : r.kind === 'return' ? r.req.retId
3349	      : r.req.docId;
3350	
3351	    let status: string;
3352	    if (outcome.duplicate) {
3353	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
3354	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
3355	    } else {
3356	      status = '首次生效';
3357	      newCount++;
3358	    }
3359	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
3360	  });
3361	
3362	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
3363	  ledger.commit(dataDir);
3364	
3365	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
3366	  for (const block of blocks) console.log(block);
3367	}
