```ts
function verifyLedgerIntegrity(store: Store): void {
  // 1. 余量连续性 + 末笔与实存一致
  const lastAfter = nullProto<Record<string, Record<string, number>>>();
  const prevByCombo = new Map<string, LedgerEntry>(); // key -> 上一条
  for (const e of store.entries) {
    const key = `${e.product}\0${e.wh}`;
    const prev = prevByCombo.get(key);
    if (prev && prev.after !== e.before)
      throw new DataError(`库存流水余量不连续：商品 ${e.product} 仓库 ${e.wh} 流水 #${prev.seq} 后余量 ${prev.after} 与 #${e.seq} 前余量 ${e.before} 不一致，数据已损坏，拒绝输出报表`);
    prevByCombo.set(key, e);
    (lastAfter[e.product] ??= nullProto())[e.wh] = e.after;
  }
  // 末笔与实存一致（双向）
  for (const [key, e] of prevByCombo) {
    const [pid, wh] = key.split('\0');
    const cur = getStock(store.stock, pid, wh);
    if (e.after !== cur) throw new DataError(`...末笔余量 ${e.after} 与当前实存 ${cur} 不一致...`);
  }
  for (const pid of Object.keys(store.stock)) {
    for (const wh of Object.keys(store.stock[pid])) {
      const v = store.stock[pid][wh];
      const last = lastAfter[pid]?.[wh];
      if (last === undefined && v !== 0) throw ...;
      if (last !== undefined && last !== v) throw ...; // 已在上一步覆盖
    }
  }
  // 2. 调拨两端完整性
  const sides = new Map<string, LedgerEntry[]>(); // `${doc}\0${product}` -> transfer entries
  for (const e of store.entries) {
    if (e.type === 'transfer' || e.type === 'transfer-rev') {
      const key = `${e.doc}\0${e.product}`;
      sides.get(key)?.push(e) ?? sides.set(key, [e]);
    }
  }
  for (const [key, list] of sides) {
    if (list.length !== 2) throw new DataError(`调拨流水两端不完整：${key} 共 ${list.length} 条...`);
    const [a, b] = list;
    // 一端 wh===from，另一端 wh===to，qty 相等，from/to 一致
    ...
  }
}
