```ts
// ---------- 期间库存对账报表 ----------

/** 带符号 BigInt 文本：正数加 +，负数保留 -，零为 0。 */
function fmtSignedBig(n: bigint): string {
  return n > 0n ? `+${n}` : String(n);
}

/**
 * 出报表前核对完整库存流水（只读，不修复）：
 * 1) 同一（商品, 仓库）流水按提交顺序余量连续（上笔后量 = 下笔前量）；
 * 2) 调拨（及冲销调拨）同一单据同一商品两端完整（调出、调入各一条，数量与方向一致）；
 * 3) 每个组合末笔余量与当前实存一致。
 * 任一不一致明确报错（数据损坏，退出 1），不输出部分报表。
 */
function verifyLedgerIntegrity(store: Store): void {
  const prevByCombo = new Map<string, LedgerEntry>();
  const lastAfter = nullProto<Record<string, Record<string, number>>>();
  for (const e of store.entries) {
    const key = JSON.stringify([e.product, e.wh]);
    const prev = prevByCombo.get(key);
    if (prev !== undefined && prev.after !== e.before)
      throw new DataError(
        `库存流水余量不连续：商品 ${e.product} 仓库 ${e.wh} 流水 #${prev.seq} 后余量 ${prev.after}，` +
          `流水 #${e.seq} 前余量 ${e.before}，数据不一致，拒绝输出对账报表（不自动修复）`,
      );
    prevByCombo.set(key, e);
    (lastAfter[e.product] ??= nullProto<Record<string, number>>())[e.wh] = e.after;
  }
  for (const [key, e] of prevByCombo) {
    const [pid, wh] = JSON.parse(key) as [string, string];
    const cur = getStock(store.stock, pid, wh);
    if (e.after !== cur)
      throw new DataError(
        `商品 ${pid} 仓库 ${wh} 末笔流水 #${e.seq} 余量 ${e.after} 与当前实存 ${cur} 不一致，` +
          `数据不一致，拒绝输出对账报表（不自动修复）`,
      );
  }
  for (const pid of Object.keys(store.stock)) {
    for (const wh of Object.keys(store.stock[pid])) {
      const cur = store.stock[pid][wh];
      const last = lastAfter[pid]?.[wh];
      if (last === undefined && cur !== 0)
        throw new DataError(
          `商品 ${pid} 仓库 ${wh} 当前实存 ${cur} 没有任何库存流水支撑，数据不一致，拒绝输出对账报表（不自动修复）`,
        );
    }
  }
  // 调拨两端完整性：同一单据同一商品必须调出、调入各一条，数量与方向一致
  const transferSides = new Map<string, LedgerEntry[]>();
  for (const e of store.entries) {
    if (e.type !== 'transfer' && e.type !== 'transfer-rev') continue;
    const key = JSON.stringify([e.doc, e.product, e.type]);
    const list = transferSides.get(key);
    if (list === undefined) transferSides.set(key, [e]);
    else list.push(e);
  }
  for (const [key, list] of transferSides) {
    const [doc, product, type] = JSON.parse(key) as [string, string, string];
    const label = type === 'transfer' ? '调拨' : '冲销调拨';
    if (list.length !== 2)
      throw new DataError(
        `${label}流水两端不完整：单据 ${doc} 商品 ${product} 只有 ${list.length} 端流水，` +
          `数据不一致，拒绝输出对账报表（不自动修复）`,
      );
    const [a, b] = list;
    if (a.from !== b.from || a.to !== b.to || a.qty !== b.qty)
      throw new DataError(`${label}流水两端不一致：单据 ${doc} 商品 ${product}...`);
    const ends = [a.wh === a.from, b.wh === b.from];
    if (ends[0] === ends[1])
      throw new DataError(`${label}流水两端仓库重复：单据 ${doc} 商品 ${product}...`);
    // 一端必须是调出仓、另一端调入仓
    if (!((a.wh === a.from && b.wh === b.to) || (a.wh === a.to && b.wh === b.from)))
      throw new DataError(...);
  }
}
```

