  // 先确定全局边界，再按商品/仓库筛选；期间 = (起点末笔流水, 终点末笔流水]
  const beginOf = nullProto<Record<string, Record<string, number>>>();
  const endOf = ...;
  const combos = new Map<string, ReconCombo>();
  const periodEntries: LedgerEntry[] = [];
  for (const e of store.entries) {
    if (e.seq <= startBound) (beginOf[e.product] ??= ...)[e.wh] = e.after;
    if (e.seq <= endBound) (endOf[e.product] ??= ...)[e.wh] = e.after;
    const inPeriod = e.seq > startBound && e.seq <= endBound;
    const match = (pid === undefined || e.product === pid) && (wid === undefined || e.wh === wid);
    if (inPeriod && match) periodEntries.push(e);
    // 候选组合：筛选匹配且（期末前有过流水）
    if (match && e.seq <= endBound) {
